#!/bin/sh
# 由 vuna 生成：分离编译构建脚本。用法: ./build.sh [OUT]
# 干净构建：一次 ocamlopt 编译全部 .mli/.ml 并链接；
# 增量构建：按 .ml/.mli/.cmi 时间戳逐模块重编（编译单元顺序即依赖顺序）。
set -eu
cd "$(dirname "$0")"
OUT=${1:-program}
FLAGS="-g -w -a+39 -warn-error +39"
MODULES="Vuna_runtime Base_dPair Base_dBool Base_dMonad Base_dMaybe Base_dEq Base_dList Base_dResult Base_dString Base_dShow Base_dOrd Prelude Vuna_dCompiler_dCommon Vuna_dCompiler_dFrontend_dToml Vuna_dCompiler_dFrontend_dManifest Vuna_dCompiler_dPackages_dPkg Vuna_dCompiler_dDebug Base_dNat Base_dVec Vuna_dCompiler_dDiagnostics Vuna_dCompiler_dFrontend_dAst Vuna_dCompiler_dFrontend_dDiagnostics Vuna_dCompiler_dFrontend_dLexer Vuna_dCompiler_dFrontend_dParser_dSupport Vuna_dCompiler_dFrontend_dParser Vuna_dCompiler_dLoader_dDiagnostics Vuna_dCompiler_dLoader_dModules Vuna_dCompiler_dLoader_dResolve Vuna_dCompiler_dLoader_dFlatten Vuna_dCompiler_dLoader Vuna_dCompiler_dCore_dTerm Vuna_dCompiler_dCore_dEval Vuna_dCompiler_dCore_dConv Vuna_dCompiler_dCore Vuna_dCompiler_dElab_dTypes Vuna_dCompiler_dElab_dPrelude Vuna_dCompiler_dElab_dSig Vuna_dCompiler_dElab_dMeta Vuna_dCompiler_dElab_dCase Vuna_dCompiler_dElab_dDict Vuna_dCompiler_dElab_dMatch Vuna_dCompiler_dElab_dTerm_dSupport Vuna_dCompiler_dElab_dTerm_dImpl Vuna_dCompiler_dElab_dTerm Vuna_dCompiler_dElab_dData Vuna_dCompiler_dElab_dTrait Vuna_dCompiler_dElab_dDerive Vuna_dCompiler_dElab_dRecords Vuna_dCompiler_dElab_dTermination_dMeasure Vuna_dCompiler_dElab_dTermination_dScc Vuna_dCompiler_dElab_dTermination Vuna_dCompiler_dElab_dDriver Vuna_dCompiler_dElab Vuna_dCompiler_dCodegen_dDecl Vuna_dCompiler_dCodegen_dErase Vuna_dCompiler_dCodegen_dTerm Vuna_dCompiler_dCodegen_dAssembly Vuna_dCompiler_dDriver_dSplit Vuna_dCompiler_dCodegen_dSplit Vuna_dCompiler_dCodegen Vuna_dCompiler_dDriver_dDt Vuna_dCompiler_dDriver_dCompile Vuna_dCompiler_dDriver_dCompilerCli Base_dIO Main "
clean=1
for m in $MODULES; do
  if [ -f "$m.cmx" ]; then clean=0; fi
done
if [ "$clean" -eq 1 ]; then
  SOURCES=""
  for m in $MODULES; do
    if [ -f "$m.mli" ]; then SOURCES="$SOURCES $m.mli"; fi
    SOURCES="$SOURCES $m.ml"
  done
  ocamlopt $FLAGS -I +unix -o "$OUT" unix.cmxa $SOURCES
  echo "built $OUT"
  exit 0
fi
compile_mod() {
  base=$1
  shift
  stale=0
  [ -f "$base.cmx" ] || stale=1
  if [ "$stale" -eq 0 ] && [ "$base.ml" -nt "$base.cmx" ]; then stale=1; fi
  if [ -f "$base.mli" ]; then
    [ -f "$base.cmi" ] || stale=1
    if [ "$stale" -eq 0 ] && [ "$base.mli" -nt "$base.cmi" ]; then stale=1; fi
  fi
  for dep in "$@"; do
    if [ "$stale" -eq 0 ] && [ -f "$dep.cmi" ] && [ "$dep.cmi" -nt "$base.cmx" ]; then stale=1; fi
    if [ "$stale" -eq 1 ]; then break; fi
  done
  if [ "$stale" -eq 1 ]; then
    echo "compile $base"
    if [ -f "$base.mli" ]; then ocamlopt $FLAGS -I +unix -c "$base.mli"; fi
    ocamlopt $FLAGS -I +unix -c "$base.ml"
  fi
}
